"""Look up label preset dimensions."""
import argparse
import json
from pathlib import Path

SOURCE = Path(__file__).with_name("catalog.json")

def load_catalog():
    return json.loads(SOURCE.read_text(encoding="utf-8"))

def list_presets():
    return sorted(load_catalog()["presets"], key=lambda row: row["id"])

def get_preset(preset_id):
    for row in load_catalog()["presets"]:
        if row["id"] == preset_id:
            return row
    raise KeyError(preset_id)

def area_mm2(preset_id):
    row = get_preset(preset_id)
    return row["width_mm"] * row["height_mm"]

def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    listing = commands.add_parser("list")
    listing.add_argument("--json", action="store_true")
    showing = commands.add_parser("show")
    showing.add_argument("preset")
    args = parser.parse_args(argv)
    if args.command == "list":
        rows = list_presets()
        if args.json:
            print(json.dumps(rows))
        else:
            for row in rows:
                print(f'{row["id"]}: {row["width_mm"]} x {row["height_mm"]} mm')
    else:
        row = get_preset(args.preset)
        print(f'{row["id"]}: {row["width_mm"]} x {row["height_mm"]} mm')

if __name__ == "__main__":
    main()

